import { useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { signOut } from "firebase/auth"; // Импортиране на signOut от Firebase
import { auth } from "../../config/firebaseConfig"; // Увери се, че Firebase конфигурацията е правилна
import { useAuth } from "../../contexts/AuthContext";

export default function Logout() {
    const navigate = useNavigate();
    const { onLogoutAdmin } = useAuth();

    useEffect(() => {
        const handleLogout = async () => {
            try {
                await signOut(auth); // Firebase функция за излизане
                onLogoutAdmin(); // Обновяване на локалния контекст
                navigate('/'); // Пренасочване към началната страница
            } catch (error) {
                console.error("Error logging out:", error);
                alert("Failed to log out. Please try again.");
            }
        };

        handleLogout();
    }, [onLogoutAdmin, navigate]);

    return null;
}
